import json

# Models currently configured in NoZar
CONFIGURED_MODELS = {
    'default': 'meta/llama-4-maverick-17b-128e-instruct',
    'support_chat': 'meta/llama-3.1-8b-instruct',
    'vision': 'google/gemma-3n-e4b-it',
    'embeddings': 'nvidia/nv-embedqa-e5-v5',
    'fraud': 'meta/llama-4-maverick-17b-128e-instruct',
}

# Known fallbacks if a model is removed
FALLBACKS = {
    'meta/llama-4-maverick-17b-128e-instruct': [
        'meta/llama-3.3-70b-instruct',
        'nvidia/llama-3.3-nemotron-super-49b-v1',
    ],
    'meta/llama-3.1-8b-instruct': [
        'meta/llama-3.2-3b-instruct',
    ],
    'google/gemma-3n-e4b-it': [
        'google/gemma-3n-e2b-it',
        'qwen/qwen3.5-122b-a10b',
    ],
    'nvidia/nv-embedqa-e5-v5': [
        'nvidia/nv-embed-v1',
        'nvidia/nv-embedqa-mistral-7b-v2',
    ],
}

# Files each model is configured in
MODEL_FILES = {
    'meta/llama-4-maverick-17b-128e-instruct': [
        'app/lib/nvidia.server.ts (DEFAULT_MODEL)',
        'app/lib/fraud-detection-ai.server.ts (NVIDIA_MODEL)',
    ],
    'meta/llama-3.1-8b-instruct': [
        'app/routes/api.support.chat.ts (model param)',
    ],
    'google/gemma-3n-e4b-it': [
        'app/lib/nvidia.server.ts (callNvidiaVision model)',
    ],
    'nvidia/nv-embedqa-e5-v5': [
        'app/lib/ai-matching.server.ts (EMBEDDING_MODEL)',
    ],
}

# Get available model IDs from API response
available = set()
try:
    raw = json.loads(items[0]['json']['body'])
    data = raw.get('data', [])
    available = set(m['id'] for m in data)
except Exception as e:
    return [{
        'json': {
            'error': f'Failed to parse models: {str(e)}',
            'configured_models': CONFIGURED_MODELS,
            'changes': []
        }
    }]

# Check each configured model
missing = []
working = []

for role, model in CONFIGURED_MODELS.items():
    if model in available:
        working.append({'role': role, 'model': model, 'status': 'ok'})
    else:
        suggestions = FALLBACKS.get(model, [])
        found_fallback = None
        for fb in suggestions:
            if fb in available:
                found_fallback = fb
                break

        missing.append({
            'role': role,
            'model': model,
            'status': 'MISSING',
            'files': MODEL_FILES.get(model, []),
            'suggested_fallback': found_fallback,
            'all_suggestions': suggestions,
        })

return [{
    'json': {
        'checked_at': str(__import__('datetime').datetime.now()),
        'total_available': len(available),
        'working': working,
        'changes': missing,
        'needs_attention': len(missing) > 0,
    }
}]
